/**
 * The project's shared framework Cache, namespaced so its groups can never
 * collide with another consumer's.
 *
 * @return \rtCamp\WPFramework\Utils\Cache Shared cache.
 */
public static function cache(): \rtCamp\WPFramework\Utils\Cache {
	static $instance = null;

	if ( null === $instance ) {
		$instance = new \rtCamp\WPFramework\Utils\Cache( '{{context_slug}}' );
	}

	return $instance;
}
